examples.code:
#include <functional>
#include <iostream>

struct M {
    M(int x) { std::cout << "M(" << x << ");\n"; }
    M() {}
};

auto operator%(M, M) {
    std::cout << "operator%(M, M);\n";
    return M{};
}
auto operator%(M, int) {
    std::cout << "operator%(M, int);\n";
    return M{};
}
auto operator%(int, M) {
    std::cout << "operator%(int, M);\n";
    return M{};
}

int main() {
    M m;

    // 42 is converted into a temporary object M{42}
    std::modulus<M>{}(m, 42); // calls operator%(M, M)

    // no temporary object
    std::modulus<void>{}(m, 42); // calls operator%(M, int)
    std::modulus<void>{}(42, m); // calls operator%(int, M)
}

